CREATE TABLE "certificate_requests" ("id" SERIAL PRIMARY KEY, "enrollment_id" INTEGER NOT NULL, "is_fee_waived" BOOLEAN NOT NULL DEFAULT false, "fee_waived_by_admin_id" INTEGER, "fee_waived_at" TIMESTAMP(3), "fee_waiver_reason" TEXT, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMP(3) NOT NULL);
CREATE UNIQUE INDEX "certificate_requests_enrollment_id_key" ON "certificate_requests"("enrollment_id");
