ALTER TABLE "certificate_requests" ADD CONSTRAINT "certificate_requests_enrollment_id_fkey" FOREIGN KEY ("enrollment_id") REFERENCES "enrollments"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "certificate_requests" ADD CONSTRAINT "certificate_requests_fee_waived_by_admin_id_fkey" FOREIGN KEY ("fee_waived_by_admin_id") REFERENCES "users"("id") ON DELETE SET NULL ON UPDATE CASCADE;
CREATE TABLE "certificate_payments" ("id" SERIAL PRIMARY KEY, "student_id" INTEGER NOT NULL, "enrollment_id" INTEGER NOT NULL, "amount" DECIMAL(10,2) NOT NULL, "currency" TEXT NOT NULL, "status" "CertificatePaymentStatus" NOT NULL DEFAULT 'PENDING', "payment_method" TEXT NOT NULL, "reference" TEXT NOT NULL, "confirmed_at" TIMESTAMP(3), "confirmed_by_admin_id" INTEGER, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMP(3) NOT NULL);
CREATE UNIQUE INDEX "certificate_payments_reference_key" ON "certificate_payments"("reference");
CREATE INDEX "certificate_payments_enrollment_id_status_idx" ON "certificate_payments"("enrollment_id","status");
CREATE INDEX "certificate_payments_student_id_idx" ON "certificate_payments"("student_id");
ALTER TABLE "certificate_payments" ADD CONSTRAINT "certificate_payments_student_id_fkey" FOREIGN KEY ("student_id") REFERENCES "users"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "certificate_payments" ADD CONSTRAINT "certificate_payments_enrollment_id_fkey" FOREIGN KEY ("enrollment_id") REFERENCES "enrollments"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "certificate_payments" ADD CONSTRAINT "certificate_payments_confirmed_by_admin_id_fkey" FOREIGN KEY ("confirmed_by_admin_id") REFERENCES "users"("id") ON DELETE SET NULL ON UPDATE CASCADE;
CREATE TABLE "certificates" ("id" SERIAL PRIMARY KEY, "certificate_request_id" INTEGER NOT NULL, "serial_number" TEXT NOT NULL, "status" "CertificateStatus" NOT NULL DEFAULT 'ISSUED', "issued_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "issued_by_admin_id" INTEGER NOT NULL, "revoked_at" TIMESTAMP(3), "revoked_by_admin_id" INTEGER, "revocation_reason" TEXT);
