CREATE UNIQUE INDEX "certificates_serial_number_key" ON "certificates"("serial_number");
CREATE INDEX "certificates_status_idx" ON "certificates"("status");
ALTER TABLE "certificates" ADD CONSTRAINT "certificates_certificate_request_id_fkey" FOREIGN KEY ("certificate_request_id") REFERENCES "certificate_requests"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "certificates" ADD CONSTRAINT "certificates_issued_by_admin_id_fkey" FOREIGN KEY ("issued_by_admin_id") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "certificates" ADD CONSTRAINT "certificates_revoked_by_admin_id_fkey" FOREIGN KEY ("revoked_by_admin_id") REFERENCES "users"("id") ON DELETE SET NULL ON UPDATE CASCADE;
